def transform(grid):
    ys=[i for i,r in enumerate(grid) if all(x==2 for x in r)]
    if len(ys)>=2:
        a,b=ys[-2],ys[-1]
        return [r[1:-1] for r in grid[a+1:b]]
    return [r[1:-1] for r in grid[11:20]]
